import sqlite3
import hashlib
import hmac
import os
import re
from flask import Flask, request, jsonify, g
from functools import wraps
import secrets

app = Flask(__name__)
DATABASE = ':memory:'
API_SECRET = os.environ.get('API_SECRET', secrets.token_hex(32))

# PBKDF2 parameters for password hashing
PBKDF2_ITERATIONS = 240000
PBKDF2_ALGO = 'sha256'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
        init_db(g.db)
    return g.db

def init_db(db):
    db.executescript('''
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY,
            username TEXT UNIQUE NOT NULL,
            display_name TEXT NOT NULL,
            password_hash TEXT NOT NULL,
            role TEXT DEFAULT 'user'
        );
        CREATE TABLE IF NOT EXISTS audit_log (
            id INTEGER PRIMARY KEY,
            actor TEXT NOT NULL,
            action TEXT NOT NULL,
            target TEXT,
            timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
        );
        CREATE TABLE IF NOT EXISTS user_preferences (
            user_id INTEGER PRIMARY KEY,
            theme TEXT DEFAULT 'light',
            sort_column TEXT DEFAULT 'username',
            sort_direction TEXT DEFAULT 'ASC',
            FOREIGN KEY (user_id) REFERENCES users(id)
        );
        INSERT OR IGNORE INTO users (username, display_name, password_hash, role)
        VALUES ('admin', 'Administrator', 'hashed_pw', 'admin');
        INSERT OR IGNORE INTO user_preferences (user_id, theme, sort_column, sort_direction)
        VALUES (1, 'dark', 'username', 'ASC');
    ''')
    db.commit()

def hash_password(password, salt=None):
    """Hash a password using PBKDF2-HMAC-SHA256 (slow, adaptive KDF)."""
    if salt is None:
        salt = secrets.token_hex(16)
    dk = hashlib.pbkdf2_hmac(
        PBKDF2_ALGO,
        password.encode(),
        salt.encode(),
        PBKDF2_ITERATIONS
    )
    return f"{PBKDF2_ALGO}${PBKDF2_ITERATIONS}${salt}${dk.hex()}"

def verify_password(password, stored):
    """Constant-time verification of a stored PBKDF2 password hash."""
    try:
        algo, iterations, salt, expected = stored.split('$')
        dk = hashlib.pbkdf2_hmac(
            algo,
            password.encode(),
            salt.encode(),
            int(iterations)
        )
        return hmac.compare_digest(dk.hex(), expected)
    except Exception:
        return False

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth = request.headers.get('Authorization', '')
        if not auth.startswith('Bearer '):
            return jsonify({'error': 'unauthorized'}), 401
        token = auth[7:]
        db = get_db()
        user = db.execute(
            'SELECT * FROM users WHERE username = ?',
            (token_to_username(token),)
        ).fetchone()
        if not user:
            return jsonify({'error': 'unauthorized'}), 401
        g.current_user = user
        return f(*args, **kwargs)
    return decorated

def token_to_username(token):
    try:
        parts = token.split(':')
        if len(parts) != 2:
            return None
        username, sig = parts
        # Use the full-length HMAC-SHA256 digest (no truncation) for signature.
        expected = hmac.new(API_SECRET.encode(), username.encode(), hashlib.sha256).hexdigest()
        if hmac.compare_digest(sig, expected):
            return username
        return None
    except Exception:
        return None

def sanitize_display_name(name):
    """Sanitize display name - allow alphanumeric, spaces, and common punctuation."""
    if not name or len(name) > 64:
        return None
    # Allow letters, numbers, spaces, hyphens, apostrophes, periods
    if not re.match(r'^[a-zA-Z0-9\s\.\-\']+$', name):
        return None
    return name

def validate_sort_column(column):
    """Validate sort column against allowed values."""
    allowed = ['username', 'display_name', 'role', 'id']
    if column in allowed:
        return column
    return 'username'

def validate_sort_direction(direction):
    """Validate sort direction."""
    if direction.upper() in ('ASC', 'DESC'):
        return direction.upper()
    return 'ASC'

def log_action(db, actor, action, target=None):
    db.execute(
        'INSERT INTO audit_log (actor, action, target) VALUES (?, ?, ?)',
        (actor, action, target)
    )
    db.commit()

@app.route('/api/register', methods=['POST'])
def register():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'invalid request'}), 400

    username = data.get('username', '')
    password = data.get('password', '')
    display_name = data.get('display_name', '')

    # Validate username - strict alphanumeric
    if not re.match(r'^[a-zA-Z0-9_]{3,32}$', username):
        return jsonify({'error': 'invalid username'}), 400

    # Validate display name
    clean_display = sanitize_display_name(display_name)
    if not clean_display:
        return jsonify({'error': 'invalid display name'}), 400

    # Hash password with a slow, adaptive KDF (PBKDF2)
    pw_hash = hash_password(password)

    db = get_db()
    try:
        db.execute(
            'INSERT INTO users (username, display_name, password_hash) VALUES (?, ?, ?)',
            (username, clean_display, pw_hash)
        )
        # Create default preferences
        user = db.execute('SELECT id FROM users WHERE username = ?', (username,)).fetchone()
        db.execute(
            'INSERT INTO user_preferences (user_id, theme, sort_column, sort_direction) VALUES (?, ?, ?, ?)',
            (user['id'], 'light', 'username', 'ASC')
        )
        db.commit()
        log_action(db, username, 'register', None)
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'username taken'}), 409

@app.route('/api/preferences', methods=['PUT'])
@require_auth
def update_preferences():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'invalid request'}), 400

    db = get_db()
    user_id = g.current_user['id']

    theme = data.get('theme', 'light')
    if theme not in ('light', 'dark', 'system'):
        theme = 'light'

    sort_column = validate_sort_column(data.get('sort_column', 'username'))
    sort_direction = validate_sort_direction(data.get('sort_direction', 'ASC'))

    db.execute(
        'UPDATE user_preferences SET theme = ?, sort_column = ?, sort_direction = ? WHERE user_id = ?',
        (theme, sort_column, sort_direction, user_id)
    )
    db.commit()
    log_action(db, g.current_user['username'], 'update_preferences', None)
    return jsonify({'status': 'updated'})

@app.route('/api/users', methods=['GET'])
@require_auth
def list_users():
    db = get_db()
    user_id = g.current_user['id']

    # Get user's preferred sort settings
    prefs = db.execute(
        'SELECT sort_column, sort_direction FROM user_preferences WHERE user_id = ?',
        (user_id,)
    ).fetchone()

    if prefs:
        sort_col = prefs['sort_column']
        sort_dir = prefs['sort_direction']
    else:
        sort_col = 'username'
        sort_dir = 'ASC'

    # Build query using stored preferences - validate again before use
    users = fetch_sorted_users(db, sort_col, sort_dir)

    return jsonify({'users': [dict(u) for u in users]})

def fetch_sorted_users(db, sort_column, sort_direction):
    """Fetch users sorted by the given column and direction.
    Re-validate before use to prevent second-order injection."""
    allowed_columns = ['username', 'display_name', 'role', 'id']
    allowed_directions = ['ASC', 'DESC']

    if sort_column not in allowed_columns:
        sort_column = 'username'
    if sort_direction not in allowed_directions:
        sort_direction = 'ASC'

    query = f"SELECT id, username, display_name, role FROM users ORDER BY {sort_column} {sort_direction}"
    return db.execute(query).fetchall()

@app.route('/api/admin/audit', methods=['GET'])
@require_auth
def get_audit_log():
    if g.current_user['role'] != 'admin':
        return jsonify({'error': 'forbidden'}), 403

    db = get_db()
    logs = db.execute('SELECT * FROM audit_log ORDER BY timestamp DESC LIMIT 100').fetchall()
    return jsonify({'logs': [dict(l) for l in logs]})

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000)
